export const meta = {
  "slug": "tabler-alert-circle",
  "family": "tabler",
  "name": "alert-circle",
  "category": "Interface",
  "motion": "shake",
  "component": "createTablerAlertCircleIcon"
};

export function createTablerAlertCircleIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
